         T_STATES_BUSR_WAIT_DATA: begin
            if (bus.rdy == 1'b1) begin
               bus_rdat_next = bus.rdat;
               timeout_next = '0;
               state_next = T_STATES_BUSR_DATA0;
            end else if (timeout[21:21] == 1'b1) begin
               uart_tx_data_next = C_TOUT;
               uart_tx_valid_next = 1'b1;
